 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Locate rectangular outline objects, whose boundary has one color.
    colors={v for row in grid for v in row if v}
    boxes=[]
    for c in colors:
        pts=[(r,x) for r in range(h) for x in range(w) if grid[r][x]==c]
        r0=min(r for r,x in pts); r1=max(r for r,x in pts); c0=min(x for r,x in pts); c1=max(x for r,x in pts)
        if all(grid[r][x]==c for r in (r0,r1) for x in range(c0,c1+1)) and all(grid[r][x]==c for r in range(r0,r1+1) for x in (c0,c1)):
            boxes.append((c,r0,r1,c0,c1))
    # The non-outline pattern is the frame with the greatest number of colored interior cells.
    patterns=[]
    for c,r0,r1,c0,c1 in boxes:
        interior=[[grid[r][x] for x in range(c0+1,c1)] for r in range(r0+1,r1)]
        patterns.append((sum(v==c for row in interior for v in row),c,interior))
    _,src,p=max(patterns,default=(0,0,[]))
    if not p or not p[0]: return [row[:] for row in grid]
    out=[row[:] for row in grid]
    for c,r0,r1,c0,c1 in boxes:
        if c==src: continue
        for r in range(r0+1,r1):
            for x in range(c0+1,c1):
                v=p[(r-r0-1)%len(p)][(x-c0-1)%len(p[0])]
                out[r][x]=c if v==src else 0
    return out
